import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("a vendor under review cannot be edited", { tag: "@VEN-09" }, async ({ apiAs }) => {
    // Arrange: a vendor in status in_review
    const member = await apiAs("member");
    const created = await member.post("/api/vendors", {
      data: {
        name: uniqueName("VEN09 Vendor"),
        category: "logistics",
        contact_email: `ops+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@acmefreight.example`,
      },
    });
    expect(created.status(), await created.text()).toBe(201);
    const vendor = (await created.json()) as { id: string };

    // Submission requires an extracted document for every required kind.
    const required: Array<{ kind: string; file: string }> = [
      { kind: "w9", file: "w9.txt" },
      { kind: "insurance_certificate", file: "insurance_certificate.txt" },
      { kind: "contract", file: "contract.txt" },
    ];
    for (const doc of required) {
      const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: doc.kind,
          file: {
            name: doc.file,
            mimeType: "text/plain",
            buffer: fs.readFileSync(sample(doc.file)),
          },
        },
      });
      expect(upload.status(), await upload.text()).toBe(201);
    }

    // Wait for background extraction of every uploaded document to finish.
    await expect
      .poll(async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/documents`);
        expect(res.status(), await res.text()).toBe(200);
        const docs = (await res.json()) as Array<{ status: string }>;
        return docs.length === required.length && docs.every((d) => d.status === "extracted");
      })
      .toBe(true);

    const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
    expect(submitted.status(), await submitted.text()).toBe(200);

    await expect
      .poll(async () => {
        const res = await member.get(`/api/vendors/${vendor.id}`);
        expect(res.status(), await res.text()).toBe(200);
        return ((await res.json()) as { status: string }).status;
      })
      .toBe("in_review");

    // Act: attempt to change the contact email
    const res = await member.patch(`/api/vendors/${vendor.id}`, {
      data: { contact_email: "billing@acmefreight.example" },
    });

    // Assert
    const body = await res.text();
    expect(res.status(), body).toBe(409);
    expect(JSON.parse(body).error.code, body).toBe("vendor_locked");
  });
});
